import java.util.*;

public class Main {
    List<Integer> insert(List<Integer> values, int insertVal) {                    // values already given starting from SOME node, in circular order
        if (values.isEmpty()) return List.of(insertVal);
        List<Integer> combined = new ArrayList<>(values);
        combined.add(insertVal);
        Collections.sort(combined);                                                  // simplest correct approach: just re-sort everything together
        return combined;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        List<Integer> values = Arrays.asList(3, 4, 1);
        System.out.println(solution.insert(values, 2));
    }
}

