vector<int> insert(vector<int>& values, int insertVal) {                          // values already given starting from SOME node, in circular order
    if (values.empty()) return {insertVal};
    vector<int> combined = values;
    combined.push_back(insertVal);
    sort(combined.begin(), combined.end());                                          // simplest correct approach: just re-sort everything together
    return combined;
}

int main() {
    vector<int> values = {3, 4, 1};
    vector<int> result = insert(values, 2);
    for (int v : result) cout << v << " ";
    cout << endl;
    return 0;
}

