import java.util.*;

public class Main {
    Node insert(Node head, int insertVal) {
        Node newNode = new Node(insertVal);
        if (head == null) {
            newNode.next = newNode;                                                     // a brand new circular list of size 1
            return newNode;
        }

        Node prev = head, curr = head.next;
        while (true) {
            if (prev.val <= insertVal && insertVal <= curr.val) break;                       // normal case: insertVal fits directly between prev and curr
            if (prev.val > curr.val) {                                                          // prev/curr straddles the max->min wrap-around point
                if (insertVal >= prev.val || insertVal <= curr.val) break;                         // insertVal is a new max OR a new min
            }
            prev = curr;
            curr = curr.next;
            if (prev == head) break;                                                            // completed a full loop: all values must be equal, insert anywhere
        }

        prev.next = newNode;
        newNode.next = curr;
        return head;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        Node n1 = new Node(1);
        Node n3 = new Node(3);
        Node n4 = new Node(4);
        n3.next = n4; n4.next = n1; n1.next = n3;
        Node result = solution.insert(n3, 2);
        StringBuilder sb = new StringBuilder();
        Node node = result;
        for (int i = 0; i < 4; i++) { sb.append(node.val).append(" "); node = node.next; }
        System.out.println(sb.toString().trim());
    }
}

